import { THINKING_SVG } from './artwork.js';

const clamp = (value, lo, hi) => Math.max(lo, Math.min(hi, value));

/** A non-interactive effect shared by every body; the selected character is never replaced. */
export function createThinkingView(host) {
  const layer = host.root.ownerDocument.createElement('div');
  layer.dataset.minduckThinking = '';
  Object.assign(layer.style, { position: 'absolute', pointerEvents: 'none', visibility: 'hidden' });
  layer.innerHTML = THINKING_SVG;
  host.root.appendChild(layer);
  const svg = layer.firstElementChild;
  const animations = svg.getAnimations({ subtree: true });
  for (const animation of animations) { animation.pause(); animation.currentTime = 0; }

  return {
    draw(seconds, layout) {
      const box = layout?.box;
      const { W, H } = host.bounds();
      if (!box || ![box.x, box.y, box.w, box.h, W, H].every(Number.isFinite)) return;
      // Fit inside the host's existing effects/halo padding and keep clear of the face.
      const padding = Math.max(24, box.w * 0.4);
      const size = Math.min(W, H, padding / 0.7, clamp(box.h * 0.42, 24, 110));
      const left = layout.facing === -1 ? box.x - size * 0.7 : box.x + box.w - size * 0.3;
      Object.assign(layer.style, {
        visibility: 'visible', left: `${clamp(left, 0, W - size)}px`,
        top: `${clamp(box.y - size * 0.6, 0, H - size)}px`,
        width: `${size}px`, height: `${size * 27 / 28}px`,
        transform: layout.facing === -1 ? 'scaleX(-1)' : '',
      });
      svg.style.width = '100%';
      svg.style.height = '100%';
      for (const animation of animations) animation.currentTime = seconds * 1000;
    },
    hide() { layer.style.visibility = 'hidden'; },
    dispose() {
      for (const animation of animations) animation.cancel();
      layer.remove();
    },
  };
}
